{
  "interpretation": {
    "name": "TightenLine3WithNR7",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Obtain the F35 tightening program, bring nutrunner NR7 to st3, tighten the fasteners, evaluate and record the result, and return the tool to the crib.",
    "constraints": [
      "get-program is executed first, before the tool is reserved or moved",
      "NR7 is reserved before use and released after it is returned to the crib",
      "NR7 is at st3 before configure-tool and tighten-fasteners",
      "transport-tool is delegated to agvexecutor",
      "the tightening program comes only from get-program, with no literal torque or tolerance values in the Recipe",
      "the tightening is evaluated and recorded (quality policy E5)",
      "every tool-using Step depends on the reserve-tool Step so it can renew the lease"
    ],
    "preference": "Release the tool before evaluation and recording so it becomes available to other lines sooner.",
    "priority": "normal",
    "horizon": "this request only (one-shot execution)",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line3-nr7-tightening-f35",
    "first_action": "PrepareProgramAndReservation",
    "actions": [
      {
        "name": "PrepareProgramAndReservation",
        "next": "BringTool",
        "steps": [
          {
            "name": "get-program-step",
            "service": "get-program",
            "next": ["reserve-tool-step"],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "reserve-tool-step",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "BringTool",
        "next": "TightenFasteners",
        "steps": [
          {
            "name": "transport-to-station-step",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "TightenFasteners",
        "next": "ReturnAndRelease",
        "steps": [
          {
            "name": "configure-tool-step",
            "service": "configure-tool",
            "next": ["tighten-fasteners-step"],
            "dep": ["get-program-step", "reserve-tool-step", "transport-to-station-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners-step",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-tool-step", "reserve-tool-step", "transport-to-station-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "ReturnAndRelease",
        "next": "EvaluateAndRecord",
        "steps": [
          {
            "name": "transport-to-crib-step",
            "service": "transport-tool",
            "next": ["release-tool-step"],
            "dep": ["reserve-tool-step", "tighten-fasteners-step"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-tool-step",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-tool-step", "transport-to-crib-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "EvaluateAndRecord",
        "next": null,
        "steps": [
          {
            "name": "evaluate-tightening-step",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step", "get-program-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening-step",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
